import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.taxCodes().listTaxCodes(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("tax_codes")) {
    Map<?, ?> taxCode = (Map<?, ?>) row;
    System.out.println(taxCode.get("id") + " " + taxCode.get("name") + " " + taxCode.get("rate"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("total"));

